// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.prank(address(this)); // admin == deployer == setUp's msg.sender
        bool ret;
        bool ok;
        try c.setOwner(newOwner) returns (bool s) {
            ret = s;
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: a successful admin setOwner always reports success (returns true).
        assertTrue(ok && ret, "admin setOwner must return true");
    }
}
